<?php
declare(strict_types=1);
require_once __DIR__.'/../../Services/authService.php';
try{$user=auth_user_from_cookie();}catch(Throwable $e){error_log($e->__toString());http_response_code(503);exit('Service indisponible.');}
if(!$user){header('Location: index.php?mode=login');exit;}
$currentPage='messages';$pageTitle='Messages';
$q=db()->prepare('SELECT c.Id_conversations,(SELECT GROUP_CONCAT(CONCAT(u.first_name," ",u.name) SEPARATOR ", ") FROM lier peer JOIN Users u ON u.Id_users=peer.Id_users WHERE peer.Id_conversations=c.Id_conversations AND peer.Id_users<>:peer_user) participants,(SELECT m.content FROM Messages m WHERE m.Id_conversations=c.Id_conversations ORDER BY m.Id_messages DESC LIMIT 1) preview,(SELECT m.created_at FROM Messages m WHERE m.Id_conversations=c.Id_conversations ORDER BY m.Id_messages DESC LIMIT 1) last_message,(SELECT COUNT(*) FROM Messages unread WHERE unread.Id_conversations=c.Id_conversations AND unread.Id_users<>:unread_sender AND unread.read_at IS NULL) unread,(SELECT MAX(u.is_online=1 AND u.last_seen>=NOW()-INTERVAL 45 SECOND) FROM lier peer JOIN Users u ON u.Id_users=peer.Id_users WHERE peer.Id_conversations=c.Id_conversations AND peer.Id_users<>:peer_online) peer_online,(SELECT MAX(u.Id_users) FROM lier peer JOIN Users u ON u.Id_users=peer.Id_users WHERE peer.Id_conversations=c.Id_conversations AND peer.Id_users<>:peer_id) peer_id FROM Conversations c JOIN lier mine ON mine.Id_conversations=c.Id_conversations WHERE mine.Id_users=:user_id ORDER BY COALESCE(last_message,c.created_at) DESC');
$q->execute(['peer_user'=>$user['Id_users'],'unread_sender'=>$user['Id_users'],'peer_online'=>$user['Id_users'],'peer_id'=>$user['Id_users'],'user_id'=>$user['Id_users']]);$conversations=$q->fetchAll();$totalUnreadMessages=array_sum(array_map(static fn($row)=>(int)$row['unread'],$conversations));$conversation=(int)($_GET['conversation']??0);$activeConversation=null;foreach($conversations as $item){if((int)$item['Id_conversations']===$conversation){$activeConversation=$item;break;}}if(!$activeConversation&&$conversations&&!isset($_GET['conversation'])){$activeConversation=$conversations[0];$conversation=(int)$activeConversation['Id_conversations'];}if(!$activeConversation)$conversation=0;
require __DIR__.'/../components/header.php';require __DIR__.'/../components/navBar.php';
?>
<style>
.chat-shell{height:calc(100dvh - 160px);min-height:420px}.chat-list-panel{width:340px;flex:none}.chat-shell{display:flex}.chat-window-panel{flex:1}.chat-bubble{max-width:min(78%,620px);overflow-wrap:anywhere}.chat-bubble.mine{margin-left:auto;background:#d9f8e9;border-radius:18px 18px 4px 18px}.chat-bubble.theirs{margin-right:auto;background:white;border:1px solid #edf0ef;border-radius:18px 18px 18px 4px}.chat-date{font-size:10px;color:#94a3a0;text-align:right;margin-top:5px}.typing-dots i{width:4px;height:4px;border-radius:50%;background:#0f9b8e;animation:typing-bounce 1s infinite ease-in-out}.typing-dots i:nth-child(2){animation-delay:.15s}.typing-dots i:nth-child(3){animation-delay:.3s}@keyframes typing-bounce{0%,60%,100%{transform:translateY(0);opacity:.45}30%{transform:translateY(-3px);opacity:1}}@media(max-width:767px){.chat-shell{height:calc(100dvh - 140px);min-height:400px;margin:-1.25rem}.chat-list-panel{width:100%;border:0}.chat-window-panel{display:none}.chat-shell.chat-open .chat-list-panel{display:none}.chat-shell.chat-open .chat-window-panel{display:flex;width:100%}}
</style>
<section id="chatShell" class="chat-shell <?= $conversation?'chat-open':'' ?> overflow-hidden rounded-none md:rounded-2xl border-y md:border border-slate-200 bg-white shadow-sm">
 <?php require __DIR__.'/../components/chatList.php'; ?>
 <div class="flex min-w-0 flex-1 flex-col"><?php require __DIR__.'/../components/chatWindow.php'; ?><?php require __DIR__.'/../components/chatInput.php'; ?></div>
</section>
<script>
(()=>{
const conversationId=<?= $conversation ?>,ownId=<?= (int)$user['Id_users'] ?>,box=document.getElementById('chatMessages'),form=document.getElementById('chatForm'),shell=document.getElementById('chatShell'),fileInput=document.getElementById('chatAttachments');
let lastId=0,loading=false,socket=null,typingSent=false,typingTimer=null,remoteTypingTimer=null;const activePeer=document.querySelector('[data-chat-item][data-conversation="'+conversationId+'"]')?.dataset.peer;if(activePeer)document.body.dataset.peerId=activePeer;
function setPresence(userId,online){document.querySelectorAll('[data-chat-item]').forEach(item=>{if(Number(item.dataset.peer)===Number(userId)){const dot=item.querySelector('[data-presence-dot]');dot?.classList.toggle('bg-emerald-500',online);dot?.classList.toggle('bg-slate-300',!online)}});if(Number(document.body.dataset.peerId||0)===Number(userId)){const dot=document.getElementById('activePresenceDot'),text=document.getElementById('activePresenceText');dot?.classList.toggle('bg-emerald-500',online);dot?.classList.toggle('bg-slate-300',!online);if(text){text.textContent=online?'En ligne':'Hors ligne';text.classList.toggle('text-emerald-600',online);text.classList.toggle('text-slate-400',!online)}}}
function sendTyping(active){if(socket&&socket.readyState===WebSocket.OPEN&&conversationId)socket.send(JSON.stringify({type:'typing',active}))}function showTyping(active,userId){if(Number(userId)===ownId)return;const indicator=document.getElementById('typingIndicator'),bubble=document.getElementById('typingBubble'),presence=document.getElementById('activePresenceText');if(!indicator||!bubble)return;clearTimeout(remoteTypingTimer);indicator.classList.toggle('hidden',!active);indicator.classList.toggle('flex',active);bubble.classList.toggle('hidden',!active);bubble.classList.toggle('flex',active);presence?.classList.toggle('hidden',active);if(active){box.append(bubble);box.scrollTop=box.scrollHeight;remoteTypingTimer=setTimeout(()=>showTyping(false,userId),3000)}}
function paintReceipt(row,message){const receipt=row.querySelector('[data-receipt]');if(!receipt||Number(message.Id_users)!==ownId)return;receipt.textContent=message.read_at?'\u2713\u2713':message.delivered_at?'\u2713\u2713':'\u2713';receipt.className='ml-1 text-[11px] '+(message.read_at?'text-sky-600':message.delivered_at?'text-slate-400':'text-slate-400')}
async function refreshChat(){if(!conversationId||!box||loading)return;loading=true;try{const response=await fetch('index.php?api=messages-list&conversation='+conversationId,{headers:{Accept:'application/json'}}),data=await response.json();if(!response.ok)throw Error(data.error||'Loading failed');const nearBottom=box.scrollHeight-box.scrollTop-box.clientHeight<100;for(const m of data.messages){const id=Number(m.Id_messages);let row=box.querySelector('[data-message-id="'+id+'"]');if(row){paintReceipt(row,m);continue}lastId=Math.max(lastId,id);row=document.createElement('article');row.dataset.messageId=String(id);row.className='chat-bubble '+(Number(m.Id_users)===ownId?'mine':'theirs')+' px-4 py-2.5 shadow-sm';if(m.content){const body=document.createElement('p');body.className='whitespace-pre-wrap text-sm leading-6 text-slate-800';body.textContent=m.content;row.append(body)}for(const attachment of (m.attachments||[])){const link=document.createElement('a');link.href=attachment.file_path;link.target='_blank';link.rel='noopener noreferrer';link.className='mt-2 flex items-center gap-2 text-sm text-teal-800 underline';if(String(attachment.mime_type).startsWith('image/')){const image=document.createElement('img');image.src=attachment.file_path;image.alt=attachment.name_original;image.className='max-h-56 max-w-full rounded-lg object-cover';link.append(image)}else{link.textContent=attachment.name_original+' ('+Math.ceil(Number(attachment.file_size)/1024)+' KB)'}row.append(link)}const time=document.createElement('div');time.className='chat-date';const date=new Date(String(m.created_at).replace(' ','T'));time.textContent=(Number(m.Id_users)===ownId?'Moi - ':'')+(Number.isNaN(date.getTime())?'':date.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}));if(Number(m.Id_users)===ownId){const receipt=document.createElement('span');receipt.dataset.receipt='';time.append(receipt)}row.append(time);paintReceipt(row,m);box.append(row)}if(data.presence){const peer=document.querySelector('[data-chat-item][data-conversation="'+conversationId+'"]')?.dataset.peer;setPresence(peer,Boolean(Number(data.presence.is_online)))}if(nearBottom)box.scrollTop=box.scrollHeight;await refreshUnread()}catch(error){console.error(error)}finally{loading=false}}
async function refreshUnread(){try{const response=await fetch('index.php?api=messages-unread'),data=await response.json();if(!response.ok)return;document.querySelectorAll('[data-chat-item]').forEach(item=>{const count=Number(data.counts?.[item.dataset.conversation]||0),badge=item.querySelector('[data-unread-badge]');if(badge){badge.textContent=String(count);badge.classList.toggle('hidden',count===0)}});let badge=document.getElementById('navMessagesBadge');const navLink=document.querySelector('a[href="index.php?page=messages"]');if(Number(data.total)>0){if(!badge&&navLink){badge=document.createElement('b');badge.id='navMessagesBadge';badge.className='ml-auto grid h-5 min-w-5 place-items-center rounded-full bg-teal-600 px-1.5 text-white text-xs';navLink.append(badge)}if(badge)badge.textContent=String(data.total)}else badge?.remove()}catch{}}
async function connectSocket(){try{const response=await fetch('index.php?api=chat-token&conversation='+conversationId),data=await response.json();if(!response.ok)throw Error('No chat ticket');const scheme=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(scheme+'://'+location.hostname+':8081?ticket='+encodeURIComponent(data.ticket));socket.addEventListener('message',event=>{let data;try{data=JSON.parse(event.data)}catch{return}if(Number(data.conversation)===conversationId){if(data.type==='presence')setPresence(data.userId,Boolean(data.online));if(data.type==='typing')showTyping(Boolean(data.active),data.userId);if(['message','read','delivery'].includes(data.type))setTimeout(refreshChat,120)}if(data.type==='unread')refreshUnread()});socket.addEventListener('close',()=>setTimeout(connectSocket,4000));socket.addEventListener('error',()=>socket.close())}catch{setTimeout(connectSocket,6000)}}
if(form){const input=form.elements.content;input.addEventListener('input',()=>{input.style.height='auto';input.style.height=Math.min(input.scrollHeight,128)+'px';if(input.value.trim()){sendTyping(true);typingSent=true;clearTimeout(typingTimer);typingTimer=setTimeout(()=>{sendTyping(false);typingSent=false},1300)}else if(typingSent){sendTyping(false);typingSent=false;clearTimeout(typingTimer)}});input.addEventListener('blur',()=>{if(typingSent){sendTyping(false);typingSent=false;clearTimeout(typingTimer)}});input.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();form.requestSubmit()}});fileInput?.addEventListener('change',()=>{const names=Array.from(fileInput.files||[]).map(file=>file.name);document.getElementById('chatAttachmentNames').textContent=names.join(', ')||'No files selected'});form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button[type="submit"]'),files=Array.from(fileInput?.files||[]);if(!input.value.trim()&&!files.length)return;if(files.length>5||files.some(file=>file.size>8*1024*1024)||files.reduce((sum,file)=>sum+file.size,0)>20*1024*1024){alert('Maximum 5 files, 8 MB each and 20 MB total.');return}button.disabled=true;if(typingSent){sendTyping(false);typingSent=false;clearTimeout(typingTimer)}try{const body=new FormData(form);body.append('conversation',conversationId);const response=await fetch('index.php?api=message-send',{method:'POST',body}),result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Message could not be sent.');form.reset();input.style.height='auto';document.getElementById('chatAttachmentNames').textContent='';await refreshChat()}catch(error){alert(error.message)}finally{button.disabled=false;input.focus()}});refreshChat();connectSocket();setInterval(()=>{if(!socket||socket.readyState!==WebSocket.OPEN)refreshChat()},2500);setInterval(refreshUnread,4000)}
document.getElementById('mobileChatBack')?.addEventListener('click',()=>shell.classList.remove('chat-open'));document.getElementById('chatSearch')?.addEventListener('input',event=>{const query=event.target.value.toLocaleLowerCase('fr');document.querySelectorAll('[data-chat-item]').forEach(item=>item.classList.toggle('hidden',!item.textContent.toLocaleLowerCase('fr').includes(query)))});if(window.lucide)lucide.createIcons()
})();
</script>
<?php require __DIR__.'/../components/footer.php'; ?>
